<template>
 <section class="full-chain" :class="{'chart-mode':mode==='chart'}">
  <template v-if="mode==='process'">
   <div class="section-heading"><div><h3>供应链全路径研判 · 五模型</h3><p>政策许可 → 矿山供给 → 加工投入品 → 铁路通道 → 验收入库 → 企业用料</p></div><span class="calculation-tag">同一冲击条件 · 分别计算</span></div>
   <div class="node-path"><span v-for="node in library.nodes" :key="node.id" :class="{hit:node.id===event.node}">{{ node.label }}</span><span>库存与用料</span></div>
   <div class="models" role="group" aria-label="全链条条件研判五模型"><button v-for="(m,i) in library.models" :key="m.id" :class="{active:m.id===model.id}" :aria-pressed="m.id===model.id" @click="update('chainModel',m.id)"><small>MODEL 0{{ i+1 }}</small><strong>{{ m.short }}</strong><span>{{ m.kind }}</span></button></div>
   <div class="controls"><label>同一采购安排 <select aria-label="过程对比采购方案" :value="plan.id" @change="update('chainPlan',$event.target.value)"><option v-for="p in library.plans" :key="p.id" :value="p.id">{{ p.label }}</option></select></label><label>检验冲击 <select aria-label="过程对比冲击" :value="event.id" @change="update('chainEvent',$event.target.value)"><option v-for="e in library.events" :key="e.id" :value="e.id">{{ e.label }}</option></select></label></div>
   <div class="workbench"><section><small>01 · 实际输入</small><h4>{{ event.label }}</h4><p>初始库存80 tU，剩余需求240 tU／70天；旧单11月10日30 tU、12月10日40 tU；期末目标40 tU。</p><p>{{ schedule(plan) }}。</p><p>节点关闭：{{ event.replay_days }}天；{{ event.exposure==='new'?'仅新增订单经过该受阻节点':'新旧订单共同经过该节点' }}。其他节点保持案例既定交付条件。</p><a v-if="event.source_url" :href="event.source_url" target="_blank" rel="noopener noreferrer">历史参数 · {{ event.publisher }} ↗</a></section><section><small>02 · 模型实际执行</small><h4>{{ model.label }}</h4><p>{{ model.definition }}</p><code v-for="f in model.formulas" :key="f">{{ f }}</code><a :href="model.source" target="_blank" rel="noopener noreferrer">专业方法来源 ↗</a></section><section><small>03 · 本次计算结果</small><h4>最大累计缺料</h4><strong class="number">{{ fmt(result.maximum_gap) }}<small> tU</small></strong><dl><div><dt>首次缺料</dt><dd>{{ result.first_shortage||'无' }}</dd></div><div><dt>缺料持续</dt><dd>{{ result.shortage_days }} 天</dd></div><div><dt>最低净库存</dt><dd>{{ fmt(result.minimum_balance) }} tU</dd></div><div><dt>期末净库存</dt><dd>{{ fmt(result.closing_balance) }} tU</dd></div><div><dt>执行状态更新</dt><dd>{{ result.operations }} 次</dd></div></dl></section></div>
   <p class="boundary">当前运行模式是有来源的事件条件推演；未估计节点事故概率或企业逐票延迟分布。模型分别执行，并不等于五份独立实证预测。{{ library.validation_scope }}</p>
   <details><summary>本次订单与70天状态记录</summary><p>{{ event.mapping }}</p><div class="table-wrap"><table><thead><tr><th>日期</th><th>入库tU</th><th>当日需求tU</th><th>净库存tU</th><th>累计欠料tU</th></tr></thead><tbody><tr v-for="(balance,i) in result.inventory_path" :key="i"><td>{{ day(i) }}</td><td>{{ fmt(result.receipt_path[i]) }}</td><td>{{ fmt(240/70,4) }}</td><td>{{ fmt(balance,4) }}</td><td>{{ fmt(Math.max(0,-balance),4) }}</td></tr></tbody></table></div></details>
  </template>
  <template v-else>
   <div class="plot-title"><span class="plot-index">01</span><div><h4>哪类冲击会造成更大缺料？五模型对照</h4><p>7种条件 × 5个模型 · 统一采购安排与计算口径</p></div></div>
   <div class="controls"><label>采购安排 <select aria-label="图一五模型采购方案" :value="plan.id" @change="update('chainPlan',$event.target.value)"><option v-for="p in library.plans" :key="p.id" :value="p.id">{{ p.label }}</option></select></label><button type="button" class="reset-plan" aria-label="图一恢复原方案" @click="update('chainPlan','staged130')">原方案</button><label>数值指标 <select aria-label="图一五模型数值指标" :value="context.chainMetric" @change="update('chainMetric',$event.target.value)"><option value="maximum_gap">最大缺料 · tU</option><option value="shortage_days">缺料天数 · 天</option><option value="minimum_balance">最低净库存 · tU</option></select></label></div>
   <div ref="plot" class="chain-chart" role="img" :aria-label="'七种供应链冲击条件下五种全链条模型的'+metric.label+'对比'"></div>
   <p class="axis-note"><b>横轴：</b>许可、投入品、物流、长停及共同通道冲击，含按期基准。<b>纵轴：</b>{{ metric.definition }}。<b>五种颜色／符号代表模型</b>，只在水平方向错开以看清同值；点击一组选择事件。</p>
   <div class="selected-event"><b>{{ event.label }} · {{ metric.label }} {{ fmt(Math.min(...values)) }}{{ Math.max(...values)!==Math.min(...values)?'—'+fmt(Math.max(...values)):'' }} {{ metric.unit }}</b><p>{{ values.every(v=>Math.abs(v-values[0])<1e-8)?'五模型在此条件下算得相同值；这核对的是条件后果，不证明独立预测准确。':'不同模型的条件计算出现差异，需逐日核对传播与状态更新。' }} {{ event.kind==='nominal'?'未加入中断。':event.replay_days+'天为节点关闭检验窗口。' }}</p></div>
   <details class="numeric"><summary>查看五模型逐项数值、参数来源与计算路径</summary><div class="table-wrap"><table><thead><tr><th>冲击条件</th><th v-for="m in library.models" :key="m.id">{{ m.short }}</th></tr></thead><tbody><tr v-for="e in library.events" :key="e.id" :class="{selected:e.id===event.id}" @click="update('chainEvent',e.id)"><th>{{ e.axis_label.replace('\n',' ') }}</th><td v-for="m in library.models" :key="m.id">{{ fmt(plan.events.find(r=>r.event_id===e.id).models[m.id][context.chainMetric]) }}</td></tr></tbody></table></div><p>{{ library.target }} {{ library.provenance_note }}</p><p>{{ event.mapping }}</p><p v-if="event.impact_boundary" class="boundary">原始披露边界：{{ event.impact_boundary }}</p><a v-if="event.source_url" :href="event.source_url" target="_blank" rel="noopener noreferrer">历史事件原始公告 ↗</a><a v-if="event.recovery_source_url" :href="event.recovery_source_url" target="_blank" rel="noopener noreferrer">恢复披露 ↗</a><p>固定采购安排：{{ schedule(plan) }}。本图共执行{{ library.checks.executed_paths }}条模型路径；最大逐日差异{{ fmt(library.checks.maximum_inventory_difference_tu,8) }} tU，只作守恒交叉核验。</p><div class="controls"><label>追溯模型 <select aria-label="图一追溯模型" :value="model.id" @change="update('chainModel',$event.target.value)"><option v-for="m in library.models" :key="m.id" :value="m.id">{{ m.label }}</option></select></label></div><div ref="trace" class="trace-chart" role="img" aria-label="所选模型在所选冲击条件下的70天库存路径"></div><p class="boundary">{{ library.interpretation }} {{ library.validation_scope }}</p></details>
  </template>
 </section>
</template>

<script setup>
import {computed,ref,watch,nextTick,onMounted,onUnmounted} from 'vue'
import * as echarts from 'echarts'
const props=defineProps({library:{type:Object,required:true},modelValue:{type:Object,required:true},mode:{type:String,default:'chart'}})
const emit=defineEmits(['update:modelValue'])
const colors=['#3264df','#029987','#d69a17','#8a5ccf','#d66078'],symbols=['circle','rect','triangle','diamond','roundRect']
const context=computed(()=>({chainPlan:'staged130',chainEvent:'case_14',chainModel:'discrete_event',chainMetric:'maximum_gap',...props.modelValue}))
const event=computed(()=>props.library.events.find(e=>e.id===context.value.chainEvent)||props.library.events.at(-1))
const model=computed(()=>props.library.models.find(m=>m.id===context.value.chainModel)||props.library.models[3])
const plan=computed(()=>props.library.plans.find(p=>p.id===context.value.chainPlan)||props.library.plans[0])
const eventRow=computed(()=>plan.value.events.find(e=>e.event_id===event.value.id))
const result=computed(()=>eventRow.value.models[model.value.id])
const values=computed(()=>props.library.models.map(m=>eventRow.value.models[m.id][context.value.chainMetric]))
const metrics={maximum_gap:{label:'最大累计缺料',unit:'tU',definition:'70天内最大累计欠料（tU），maxₜ max(0,−Iₜ)；0表示此条件下没有物理欠料'},shortage_days:{label:'缺料天数',unit:'天',definition:'70天中日末净库存小于0的天数（天），不是中断发生概率'},minimum_balance:{label:'最低净库存',unit:'tU',definition:'70天内最低净库存（tU）；正值为库存裕量、负值绝对值为最大欠料'}}
const metric=computed(()=>metrics[context.value.chainMetric]||metrics.maximum_gap)
const plot=ref(null),trace=ref(null);let chart,traceChart,observer,alive=true
const fmt=(v,d=2)=>Number(v).toLocaleString('zh-CN',{maximumFractionDigits:d})
const day=i=>new Date(Date.UTC(2026,9,23+i)).toISOString().slice(0,10)
const schedule=p=>p.new_receipts.map(r=>`${r.date.slice(5)}可用${r.quantity} tU`).join('；')
function update(key,value){emit('update:modelValue',{...context.value,[key]:value})}
const common={animation:false,color:colors,textStyle:{fontFamily:'Microsoft YaHei, sans-serif',fontSize:10,color:'#667b92'}}
async function render(){await nextTick();if(!alive||props.mode!=='chart')return
 if(plot.value?.clientWidth){chart ||= echarts.init(plot.value);chart.setOption({...common,legend:{top:1,left:3,itemWidth:10,itemHeight:8,textStyle:{fontSize:10},data:props.library.models.map(m=>m.short)},grid:{left:48,right:15,top:61,bottom:52},tooltip:{trigger:'axis',confine:true,textStyle:{fontSize:11},formatter:params=>{if(!params.length)return '';const e=props.library.events[params[0].dataIndex];return `<b>${e.label}</b><br>`+params.map(p=>`${p.marker}${p.seriesName}：${fmt(p.value)} ${metric.value.unit}`).join('<br>')}},xAxis:{type:'category',boundaryGap:true,data:props.library.events.map(e=>e.axis_label),axisTick:{show:false},axisLine:{lineStyle:{color:'#d8e1eb'}},axisLabel:{fontSize:9,lineHeight:14,interval:0}},yAxis:{type:'value',name:metric.value.label+'（'+metric.value.unit+'）',nameTextStyle:{fontSize:10},splitLine:{lineStyle:{color:'#edf1f6'}}},series:props.library.models.map((m,i)=>({name:m.short,type:'scatter',symbol:symbols[i],symbolSize:7,symbolOffset:[(i-2)*8,0],data:plan.value.events.map(e=>e.models[m.id][context.value.chainMetric]),label:{show:i===2,position:'top',distance:10,fontSize:10,color:'#52677e',formatter:p=>fmt(p.value)},emphasis:{scale:1.7}}))},true);chart.off('click');chart.on('click',p=>update('chainEvent',props.library.events[p.dataIndex].id))}
 if(trace.value?.clientWidth){traceChart ||= echarts.init(trace.value);traceChart.setOption({...common,grid:{left:50,right:10,top:25,bottom:28},tooltip:{trigger:'axis',confine:true,valueFormatter:v=>fmt(v)+' tU'},xAxis:{type:'category',data:result.value.inventory_path.map((_,i)=>day(i).slice(5)),boundaryGap:false,axisLabel:{interval:13}},yAxis:{type:'value',name:'日末净库存(tU)',splitLine:{lineStyle:{color:'#edf1f6'}}},series:[{name:model.value.short,type:'line',data:result.value.inventory_path,showSymbol:false,lineStyle:{width:2,color:colors[props.library.models.indexOf(model.value)]},markLine:{symbol:'none',silent:true,lineStyle:{type:'dashed',color:'#ba8792'},data:[{yAxis:0,label:{show:false}}]}}]},true)}
}
watch([()=>props.modelValue,()=>props.library],render,{deep:true})
onMounted(()=>{render();observer=new ResizeObserver(()=>{chart?.resize();traceChart?.resize();render()});if(plot.value)observer.observe(plot.value);if(trace.value)observer.observe(trace.value)})
onUnmounted(()=>{alive=false;observer?.disconnect();chart?.dispose();traceChart?.dispose()})
</script>

<style scoped>
